package com.bank.qa.triage;

// A defect records severity and priority as SEPARATE independent fields.
class Defect {
    private final String id;
    private final String summary;
    private final Severity severity;     // impact
    private final Priority priority;     // urgency
    private final int affectedUsers;     // helps justify priority
    private final boolean hasWorkaround; // helps justify priority

    Defect(String id, String summary, Severity severity, Priority priority,
           int affectedUsers, boolean hasWorkaround) {
        this.id = id; this.summary = summary;
        this.severity = severity; this.priority = priority;
        this.affectedUsers = affectedUsers; this.hasWorkaround = hasWorkaround;
    }

    String getId() { return id; }
    String getSummary() { return summary; }
    Severity getSeverity() { return severity; }
    Priority getPriority() { return priority; }
    int getAffectedUsers() { return affectedUsers; }
    boolean hasWorkaround() { return hasWorkaround; }
}
