package com.bank.qa.triage;

import java.util.List;
import java.util.logging.*;

public class DefectTriageDemo {
    private static final Logger log = Logger.getLogger(DefectTriageDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new TriageLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        List<Defect> defects = List.of(
            new Defect("BUG-101", "Bank name misspelled on public homepage",
                Severity.TRIVIAL, Priority.P1_IMMEDIATE, 50000, true),
            new Defect("BUG-102", "Crash in monthly admin export edge case",
                Severity.CRITICAL, Priority.P4_LOW, 1, true),
            new Defect("BUG-103", "Transfer debits wrong amount",
                Severity.CRITICAL, Priority.P1_IMMEDIATE, 1200, false),
            new Defect("BUG-104", "Settings page icon slightly misaligned",
                Severity.TRIVIAL, Priority.P4_LOW, 30, true)
        );

        TriageService triage = new TriageService();

        log.info("=== Explaining each defect's severity/priority ===");
        defects.forEach(triage::explain);

        log.info("=== Fix order (driven by business PRIORITY) ===");
        for (Defect d : triage.orderForFixing(defects)) {
            log.info(d.getPriority() + "  " + d.getId() + "  (" + d.getSeverity()
                    + ")  " + d.getSummary());
        }
    }
}

// ─── Would be in TriageLogFormatter.java in a real project ───
class TriageLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
